SELECT ap_patients.deathtime, ap_patients.los, p90_patients.p90_value, (SELECT COUNT(*) FROM labevents WHERE labevents.itemid = 720571 AND labevents.charttime BETWEEN ap_patients.admittime AND ap_patients.dischtime AND labevents.value > p90_patients.p90_value) AS critical_lab_events, (SELECT COUNT(*) FROM labevents WHERE labevents.itemid = 720571 AND labevents.charttime BETWEEN ap_patients.admittime AND ap_patients.dischtime AND labevents.value <= p90_patients.p90_value) AS stable_lab_events FROM ap_patients JOIN p90_patients ON ap_patients.subject_id = p90_patients.subject_id;